cd repro
rm src/app/app.html src/app/app.css src/app/app.spec.ts
# add the files below
npx ng build   # the default app.routes.server.ts prerenders '**', so the build renders '/' on the server
node dist/repro/server/server.mjs
# open http://localhost:4000/ and click "toggle"
```

`src/app/container.ts`

```ts
import { Component, input } from '@angular/core';

@Component({
  selector: 'app-container',
  template: `
    @if (open()) {
      <ng-content />
    }
  `,
})
export class ContainerComponent {
  readonly open = input(false);
}
```

`src/app/wrapper.ts`

```ts
import { Component, input } from '@angular/core';
import { ContainerComponent } from './container';

@Component({
  selector: 'app-wrapper',
  imports: [ContainerComponent],
  template: `
    <app-container [open]="open()">
      <div><ng-content /></div>
    </app-container>
  `,
})
export class WrapperComponent {
  readonly open = input(false);
}
```

`src/app/app.ts`

```ts
import { Component, signal } from '@angular/core';
import { WrapperComponent } from './wrapper';

@Component({
  selector: 'app-root',
  imports: [WrapperComponent],
  template: `
    <button id="toggle" (click)="open.set(!open())">toggle</button>
    <app-wrapper [open]="open()">projected text</app-wrapper>
  `,
})
export class App {
  protected readonly open = signal(false);
}
```

`src/app/app.config.ts` (the generated providers, unchanged)

```ts
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideClientHydration } from '@angular/platform-browser';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [provideBrowserGlobalErrorListeners(), provideRouter(routes), provideClientHydration()],
};
```

`src/app/app.config.server.ts` and `src/app/app.routes.server.ts` are the generated ones (`provideServerRendering(withRoutes(serverRoutes))`, `{ path: '**', renderMode: RenderMode.Prerender }`). To serve the build on `localhost`, `angular.json` has `"allowedHosts": ["localhost"]` under `security`.

### Please provide the exception or error you saw

There is no exception. The prerendered `/` (production build) is:

```html
<app-root ng-version="22.3.0" ngh="2" ng-server-context="ssg"><button id="toggle" jsaction="click:;">toggle</button><app-wrapper ngh="1"><app-container ngh="0"><!----></app-container></app-wrapper></app-root>
```

